module tsp_portal_solver(\n    input clk,\n    input rst_n,\n    input start,\n    input [9:0] x0, y0, z0,\n    input [9:0] x1, y1, z1,\n    input [9:0] x2, y2, z2,\n    input [9:0] x3, y3, z3,\n    output reg [15:0] result,\n    output reg done\n);\n\n    // Input capture registers\n    reg [9:0] x0_reg, x1_reg, x2_reg, x3_reg;\n    reg [9:0] y0_reg, y1_reg, y2_reg, y3_reg;\n    reg [9:0] z0_reg, z1_reg, z2_reg, z3_reg;\n    reg start_dly;\n\n    // Function for absolute difference\n    function [10:0] abs_diff(input [9:0] a, b);\n        abs_diff = (a > b) ? (a - b) : (b - a);\n    endfunction\n\n    // Function to calculate permutation cost\n    function [15:0] perm_cost(\n        input [13:0] e0, e1, e2, e3\n    );\n        reg [15:0] total;\n        reg [14:0] pair1, pair2;\n        begin\n            total = e0 + e1 + e2 + e3;\n            pair1 = e0 + e2;\n            pair2 = e1 + e3;\n            perm_cost = total - (pair1 > pair2 ? pair1 : pair2);\n        end\n    endfunction\n\n    // Pairwise distance calculations\n    wire [13:0] d01 = abs_diff(x0_reg, x1_reg) + abs_diff(y0_reg, y1_reg) + abs_diff(z0_reg, z1_reg);\n    wire [13:0] d02 = abs_diff(x0_reg, x2_reg) + abs_diff(y0_reg, y2_reg) + abs_diff(z0_reg, z2_reg);\n    wire [13:0] d03 = abs_diff(x0_reg, x3_reg) + abs_diff(y0_reg, y3_reg) + abs_diff(z0_reg, z3_reg);\n    wire [13:0] d12 = abs_diff(x1_reg, x2_reg) + abs_diff(y1_reg, y2_reg) + abs_diff(z1_reg, z2_reg);\n    wire [13:0] d13 = abs_diff(x1_reg, x3_reg) + abs_diff(y1_reg, y3_reg) + abs_diff(z1_reg, z3_reg);\n    wire [13:0] d23 = abs_diff(x2_reg, x3_reg) + abs_diff(y2_reg, y3_reg) + abs_diff(z2_reg, z3_reg);\n\n    // Permutation costs\n    wire [15:0] cost_p1 = perm_cost(d01, d12, d23, d03);\n    wire [15:0] cost_p2 = perm_cost(d01, d13, d23, d02);\n    wire [15:0] cost_p3 = perm_cost(d02, d12, d13, d03);\n    wire [15:0] cost_p4 = perm_cost(d02, d23, d13, d01);\n    wire [15:0] cost_p5 = perm_cost(d03, d13, d12, d02);\n    wire [15:0] cost_p6 = perm_cost(d03, d23, d12, d01);\n\n    // Minimum calculation tree\n    wire [15:0] min12 = (cost_p1 < cost_p2) ? cost_p1 : cost_p2;\n    wire [15:0] min34 = (cost_p3 < cost_p4) ? cost_p3 : cost_p4;\n    wire [15:0] min56 = (cost_p5 < cost_p6) ? cost_p5 : cost_p6;\n    wire [15:0] min1234 = (min12 < min34) ? min12 : min34;\n    wire [15:0] min_total = (min1234 < min56) ? min1234 : min56;\n\n    // Sequential control\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            x0_reg <= 10'd0;\n            y0_reg <= 10'd0;\n            z0_reg <= 10'd0;\n            x1_reg <= 10'd0;\n            y1_reg <= 10'd0;\n            z1_reg <= 10'd0;\n            x2_reg <= 10'd0;\n            y2_reg <= 10'd0;\n            z2_reg <= 10'd0;\n            x3_reg <= 10'd0;\n            y3_reg <= 10'd0;\n            z3_reg <= 10'd0;\n            start_dly <= 1'b0;\n            done <= 1'b0;\n            result <= 16'd0;\n        end else begin\n            // Input capture\n            if (start) begin\n                x0_reg <= x0; y0_reg <= y0; z0_reg <= z0;\n                x1_reg <= x1; y1_reg <= y1; z1_reg <= z1;\n                x2_reg <= x2; y2_reg <= y2; z2_reg <= z2;\n                x3_reg <= x3; y3_reg <= y3; z3_reg <= z3;\n            end\n\n            // Result calculation\n            start_dly <= start;\n            if (start_dly) begin\n                result <= min_total;\n            end\n\n            // Done generation\n            done <= start_dly;\n        end\n    end\n\nendmodule